# ! [doc = " A library for acquiring a backtrace at runtime"] # ! [doc = ""] # ! [doc = " This library is meant to supplement the `RUST_BACKTRACE=1` support of the"] # ! [doc = " standard library by allowing an acquisition of a backtrace at runtime"] # ! [doc = " programmatically. The backtraces generated by this library do not need to be"] # ! [doc = " parsed, for example, and expose the functionality of multiple backend"] # ! [doc = " implementations."] # ! [doc = ""] # ! [doc = " # Usage"] # ! [doc = ""] # ! [doc = " First, add this to your Cargo.toml"] # ! [doc = ""] # ! [doc = " ```toml"] # ! [doc = " [dependencies]"] # ! [doc = " backtrace = \"0.3\""] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Next:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # // Unsafe here so test passes on no_std."] # ! [doc = " # #[cfg(feature = \"std\")] {"] # ! [doc = " backtrace::trace(|frame| {"] # ! [doc = "     let ip = frame.ip();"] # ! [doc = "     let symbol_address = frame.symbol_address();"] # ! [doc = ""] # ! [doc = "     // Resolve this instruction pointer to a symbol name"] # ! [doc = "     backtrace::resolve_frame(frame, |symbol| {"] # ! [doc = "         if let Some(name) = symbol.name() {"] # ! [doc = "             // ..."] # ! [doc = "         }"] # ! [doc = "         if let Some(filename) = symbol.filename() {"] # ! [doc = "             // ..."] # ! [doc = "         }"] # ! [doc = "     });"] # ! [doc = ""] # ! [doc = "     true // keep going to the next frame"] # ! [doc = " });"] # ! [doc = " # }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # Backtrace accuracy"] # ! [doc = ""] # ! [doc = " This crate implements best-effort attempts to get the native backtrace. This"] # ! [doc = " is not always guaranteed to work, and some platforms don't return any"] # ! [doc = " backtrace at all. If your application requires accurate backtraces then it's"] # ! [doc = " recommended to closely evaluate this crate to see whether it's suitable"] # ! [doc = " for your use case on your target platforms."] # ! [doc = ""] # ! [doc = " Even on supported platforms, there's a number of reasons that backtraces may"] # ! [doc = " be less-than-accurate, including but not limited to:"] # ! [doc = ""] # ! [doc = " * Unwind information may not be available. This crate primarily implements"] # ! [doc = "   backtraces by unwinding the stack, but not all functions may have"] # ! [doc = "   unwinding information (e.g. DWARF unwinding information)."] # ! [doc = ""] # ! [doc = " * Rust code may be compiled without unwinding information for some"] # ! [doc = "   functions. This can also happen for Rust code compiled with"] # ! [doc = "   `-Cpanic=abort`. You can remedy this, however, with"] # ! [doc = "   `-Cforce-unwind-tables` as a compiler option."] # ! [doc = ""] # ! [doc = " * Unwind information may be inaccurate or corrupt. In the worst case"] # ! [doc = "   inaccurate unwind information can lead this library to segfault. In the"] # ! [doc = "   best case inaccurate information will result in a truncated stack trace."] # ! [doc = ""] # ! [doc = " * Backtraces may not report filenames/line numbers correctly due to missing"] # ! [doc = "   or corrupt debug information. This won't lead to segfaults unlike corrupt"] # ! [doc = "   unwinding information, but missing or malformed debug information will"] # ! [doc = "   mean that filenames and line numbers will not be available. This may be"] # ! [doc = "   because debug information wasn't generated by the compiler, or it's just"] # ! [doc = "   missing on the filesystem."] # ! [doc = ""] # ! [doc = " * Not all platforms are supported. For example there's no way to get a"] # ! [doc = "   backtrace on WebAssembly at the moment."] # ! [doc = ""] # ! [doc = " * Crate features may be disabled. Currently this crate supports using Gimli"] # ! [doc = "   libbacktrace on non-Windows platforms for reading debuginfo for"] # ! [doc = "   backtraces. If both crate features are disabled, however, then these"] # ! [doc = "   platforms will generate a backtrace but be unable to generate symbols for"] # ! [doc = "   it."] # ! [doc = ""] # ! [doc = " In most standard workflows for most standard platforms you generally don't"] # ! [doc = " need to worry about these caveats. We'll try to fix ones where we can over"] # ! [doc = " time, but otherwise it's important to be aware of the limitations of"] # ! [doc = " unwinding-based backtraces!"] # ! [deny (missing_docs)] # ! [no_std] # ! [cfg_attr (all (feature = "std" , target_env = "sgx" , target_vendor = "fortanix") , feature (sgx_platform))] # ! [warn (rust_2018_idioms)] # ! [cfg_attr (backtrace_in_libstd , allow (warnings))] # ! [cfg_attr (not (feature = "std") , allow (dead_code))] use split_decls_genesis :: ourprelude :: * ; #[cfg (feature = "std")] #[macro_use] extern crate std ; #[allow (unused_extern_crates)] extern crate alloc ; pub use self :: backtrace :: { trace_unsynchronized , Frame } ; mod backtrace ; pub use self :: symbolize :: resolve_frame_unsynchronized ; pub use self :: symbolize :: { resolve_unsynchronized , Symbol , SymbolName } ; mod symbolize ; pub use self :: types :: BytesOrWideString ; mod types ; #[cfg (feature = "std")] pub use self :: symbolize :: clear_symbol_cache ; mod print ; pub use print :: { BacktraceFmt , BacktraceFrameFmt , PrintFmt } ; cfg_if :: cfg_if ! { if #[cfg (feature = "std")] { pub use self :: backtrace :: trace ; pub use self :: symbolize :: { resolve , resolve_frame } ; pub use self :: capture :: { Backtrace , BacktraceFrame , BacktraceSymbol } ; mod capture ; } } cfg_if :: cfg_if ! { if #[cfg (all (target_env = "sgx" , target_vendor = "fortanix" , not (feature = "std")))] { pub use self :: backtrace :: set_image_base ; } } #[cfg (feature = "std")] mod lock { use std :: boxed :: Box ; use std :: cell :: Cell ; use std :: ptr ; use std :: sync :: { Mutex , MutexGuard , Once } ; #[doc = " A \"Maybe\" LockGuard"] pub struct LockGuard (Option < MutexGuard < 'static , () > >) ; #[doc = " The global lock, lazily allocated on first use"] static mut LOCK : * mut Mutex < () > = ptr :: null_mut () ; static INIT : Once = Once :: new () ; thread_local ! (static LOCK_HELD : Cell < bool > = const { Cell :: new (false) }) ; impl Drop for LockGuard { fn drop (& mut self) { if self . 0 . is_some () { LOCK_HELD . with (| slot | { assert ! (slot . get ()) ; slot . set (false) ; }) ; } } } #[doc = " Acquire a partially unsound(!!!) global re-entrant lock over"] #[doc = " backtrace's internals."] #[doc = ""] #[doc = " That is, this lock can be acquired as many times as you want"] #[doc = " on a single thread without deadlocking, allowing one thread"] #[doc = " to acquire exclusive access to the ability to make backtraces."] #[doc = " Calls to this locking function are freely sprinkled in every place"] #[doc = " where that needs to be enforced."] #[doc = ""] #[doc = ""] #[doc = " # Why"] #[doc = ""] #[doc = " This was first introduced to guard uses of Windows' dbghelp API,"] #[doc = " which isn't threadsafe. It's unclear if other things now rely on"] #[doc = " this locking."] #[doc = ""] #[doc = ""] #[doc = " # How"] #[doc = ""] #[doc = " The basic idea is to have a single global mutex, and a thread_local"] #[doc = " boolean saying \"yep this is the thread that acquired the mutex\"."] #[doc = ""] #[doc = " The first time a thread acquires the lock, it is handed a"] #[doc = " `LockGuard(Some(..))` that will actually release the lock on Drop."] #[doc = " All subsequence attempts to lock on the same thread will see"] #[doc = " that their thread acquired the lock, and get `LockGuard(None)`"] #[doc = " which will do nothing when dropped."] #[doc = ""] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " As long as you only ever assign the returned LockGuard to a freshly"] #[doc = " declared local variable, it will do its job correctly, as the \"first\""] #[doc = " LockGuard will strictly outlive all subsequent LockGuards and"] #[doc = " properly release the lock when the thread is done with backtracing."] #[doc = ""] #[doc = " However if you ever attempt to store a LockGuard beyond the scope"] #[doc = " it was acquired in, it might actually be a `LockGuard(None)` that"] #[doc = " doesn't actually hold the lock! In this case another thread might"] #[doc = " acquire the lock and you'll get races this system was intended to"] #[doc = " avoid!"] #[doc = ""] #[doc = " This is why this is \"partially unsound\". As a public API this would"] #[doc = " be unacceptable, but this is crate-private, and if you use this in"] #[doc = " the most obvious and simplistic way it Just Works™."] #[doc = ""] #[doc = " Note however that std specifically bypasses this lock, and uses"] #[doc = " the `*_unsynchronized` backtrace APIs. This is \"fine\" because"] #[doc = " it wraps its own calls to backtrace in a non-reentrant Mutex"] #[doc = " that prevents two backtraces from getting interleaved during printing."] pub fn lock () -> LockGuard { if LOCK_HELD . with (| l | l . get ()) { return LockGuard (None) ; } LOCK_HELD . with (| s | s . set (true)) ; unsafe { INIT . call_once (| | { LOCK = Box :: into_raw (Box :: new (Mutex :: new (()))) ; }) ; LockGuard (Some ((* LOCK) . lock () . unwrap ())) } } } #[cfg (all (windows , any (target_env = "msvc" , all (target_env = "gnu" , any (target_arch = "x86" , target_arch = "arm"))) , not (target_vendor = "uwp")))] mod dbghelp ; #[cfg (any (windows , target_os = "cygwin"))] mod windows_sys ;